import type {StudyInput,NextDesignInput,ExperimentFeedback} from '../../../packages/contracts/src/next-experiment.js';
import {randomUUID} from 'node:crypto';
export function studyFixture():StudyInput{return {expectedProjectRevision:1,materialSystem:'Synthetic validation material, not a real experiment',question:'Synthetic response design',hypotheses:[{statement:'Synthetic response changes with factor',alternative:'Uncontrolled batch differences',falsification:'Control-adjusted response does not change'}],snapshotIds:[],experimentalUnit:'One independently prepared synthetic specimen',measurementConditions:'Synthetic fixture: fixed condition',response:{metric:'reported',property:'synthetic_response',unit:'MPa',direction:'maximize',target:null},factors:[{key:'temperature',label:'Synthetic temperature',unit:'C',kind:'continuous',levels:[0,1],costPerUnitCny:2}],constraints:[],control:{temperature:0},blocks:['batch-a','batch-b'],replicates:2,baseCostCny:10,minutesPerRun:5,costBasis:'Synthetic assumed cost',maxCostCny:10000,maxMinutes:10000,maxRuns:400,manufacturabilityNotes:'Synthetic, physical manufacturability not established'};}
export function designFixture(studyId=randomUUID()):NextDesignInput{return {studyId,method:'factorial',points:8,seed:2026,reason:'Synthetic test, no physical experiment'};}
export function smoothFeedback(count=24):ExperimentFeedback[]{return Array.from({length:count},(_,i)=>{const x=i/(count-1);return {id:randomUUID(),projectId:randomUUID(),studyId:randomUUID(),createdAt:new Date().toISOString(),sha256:'a'.repeat(64),input:{expectedProjectRevision:1,designId:randomUUID(),plannedRunId:'planned-'+i,outcome:'measured',actualFactors:{temperature:x},reviewed:true,notes:'Synthetic test data, not a real measurement',supersedes:null,source:{kind:'reported',snapshotId:randomUUID(),observationId:'obs-'+i}},value:100+20*Math.sin(3*x),unit:'MPa',sourceSnapshotIds:[],sourceIdentity:'synthetic:'+i,conditions:'Synthetic fixture: fixed condition',evidence:[],scientificStatus:'needs_review',deviations:[]};});}
